import{_ as a}from"./chunks/dashboard-home-stopped.DxCzv0yb.js";import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.Dhf_H6O0.js";const b=JSON.parse('{"title":"Your First Launch","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/first-launch.md","filePath":"getting-started/first-launch.md"}'),n={name:"getting-started/first-launch.md"};function i(d,t,h,l,g,c){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="your-first-launch" tabindex="-1">Your First Launch <a class="header-anchor" href="#your-first-launch" aria-label="Permalink to &quot;Your First Launch&quot;">​</a></h1><p>After activating your license, you&#39;ll see the MCPBehindIT Dashboard. This is your home base for managing the MCP gateway.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p><img src="'+a+'" alt="MCPBehindIT Dashboard in stopped state"></p><p>The Dashboard has three main areas:</p><h3 id="phase-strip" tabindex="-1">Phase strip <a class="header-anchor" href="#phase-strip" aria-label="Permalink to &quot;Phase strip&quot;">​</a></h3><p>The bar at the top shows the current state of each component:</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>DOCKER</strong> Reachable (green)</td><td>Docker Desktop is running and accessible</td></tr><tr><td><strong>GATEWAY</strong> Stopped (gray)</td><td>The MCP gateway container is not running yet</td></tr><tr><td><strong>SERVERS</strong> 1 enabled / 1 total</td><td>How many server profiles you have and how many are active</td></tr></tbody></table><h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><ul><li><strong>Stack</strong> — Start, stop, and monitor the gateway.</li><li><strong>Clients</strong> — Copy connection URLs for your AI tools (visible once the gateway is running).</li><li><strong>Documents</strong> — Manage local document indexing for RAG search.</li></ul><h3 id="tool-gateway-card" tabindex="-1">Tool gateway card <a class="header-anchor" href="#tool-gateway-card" aria-label="Permalink to &quot;Tool gateway card&quot;">​</a></h3><p>Shows the gateway status and provides the <strong>Start</strong>, <strong>Stop</strong>, and <strong>Apply &amp; Restart</strong> buttons.</p><h2 id="starting-the-gateway-for-the-first-time" tabindex="-1">Starting the gateway for the first time <a class="header-anchor" href="#starting-the-gateway-for-the-first-time" aria-label="Permalink to &quot;Starting the gateway for the first time&quot;">​</a></h2><ol><li>Make sure the <strong>DOCKER</strong> indicator is green.</li><li>Click <strong>Start</strong>.</li><li>The app pulls the gateway Docker image (first time only — about 200 MB). You&#39;ll see a progress log.</li><li>Once the gateway is running, the status badge in the top-right corner changes to <strong>Running</strong> (green).</li></ol><div class="tip custom-block"><p class="custom-block-title">No servers yet?</p><p>If you haven&#39;t added any servers, the gateway starts but has nothing to serve. That&#39;s fine! Head to the <a href="./../catalog/browsing.html">Catalog</a> to add your first server, then click <strong>Apply &amp; Restart</strong> on the Dashboard.</p></div><h2 id="sidebar-navigation" tabindex="-1">Sidebar navigation <a class="header-anchor" href="#sidebar-navigation" aria-label="Permalink to &quot;Sidebar navigation&quot;">​</a></h2><p>The sidebar on the left gives you access to all sections:</p><table tabindex="0"><thead><tr><th>Section</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Home</strong></td><td>Dashboard — start/stop gateway, view status, copy URLs</td></tr><tr><td><strong>Servers</strong></td><td>Add, edit, and manage your MCP server definitions</td></tr><tr><td><strong>Catalog</strong></td><td>Browse pre-configured servers (Telecontext, Local RAG)</td></tr><tr><td><strong>Logs</strong></td><td>View real-time container logs from the gateway</td></tr><tr><td><strong>Import</strong></td><td>Bulk-import server definitions from JSON</td></tr><tr><td><strong>About</strong></td><td>Version info and links</td></tr><tr><td><strong>Settings</strong></td><td>License key, gateway port, Docker resources, advanced mode</td></tr></tbody></table><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./../using-the-app/start-gateway.html">Start the gateway</a> and learn what happens behind the scenes.</li><li><a href="./../catalog/browsing.html">Add a server from the Catalog</a> — try Telecontext or Local RAG.</li><li><a href="./../using-the-app/manage-servers.html">Add your own server</a> manually.</li></ul>',20)])])}const m=e(n,[["render",i]]);export{b as __pageData,m as default};
